/**
 * TwelveLittleScoutsClerk per-event settlement ("Abrechnung") report renderer
 *
 * Builds an HTML report for one event similar in spirit to the manual
 * "Abrechnung SoLa GuSp 2025.xlsx" sheet (budget top, expenses grouped by
 * account class, itemized booking lines and a remaining-budget summary), but
 * computed from the data stored in the database for that event.
 *
 * @author Copyright (c) 2026 Martin Oberzalek
 */
// generated by AI (GitHub Copilot / Claude Sonnet 4.6)
package at.redeye.twelvelittlescoutsclerk.reports.eventsettlement;

import at.redeye.FrameWork.base.AutoLogger;
import at.redeye.FrameWork.base.reports.BaseReportRenderer;
import at.redeye.FrameWork.base.reports.ReportRenderer;
import at.redeye.FrameWork.base.transaction.Transaction;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBBookingLine;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBBookingLine2Events;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBBillingPeriod;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBEvent;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBEventMember;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

// AI-generated start (GitHub Copilot / Claude Sonnet 4.6)
public class ReportEventSettlementRenderer extends BaseReportRenderer implements ReportRenderer {

    private static final String UNASSIGNED = "(unassigned)";

    private final Transaction trans;
    private final DBEvent event;
    private final DBBillingPeriod bp;

    // ---- collected data (filled by doRender) ----
    private List<DBEventMember> members = new ArrayList<>();
    private List<DBBookingLine> bookingLines = new ArrayList<>();
    private double bookingLinesTotal = 0.0;   // signed sum over all linked booking lines
    private double plannedBudget = 0.0;       // planned income for the event
    private double feePerPerson = 0.0;

    public ReportEventSettlementRenderer(Transaction trans, DBEvent event, DBBillingPeriod bp) {
        this.trans = trans;
        this.event = event;
        this.bp = bp;
    }

    @Override
    public boolean collectData() {
        return true; // data is fetched inline in render()
    }

    @Override
    public String render() {
        AutoLogger al = new AutoLogger(ReportEventSettlementRenderer.class.getSimpleName()) {
            @Override
            public void do_stuff() throws Exception {
                result = doRender();
            }
        };
        if (al.result instanceof String) {
            return (String) al.result;
        }
        return "<html><body>Error generating report</body></html>";
    }

    private String doRender() throws Exception {
        // ---- participants (EVENTMEMBERS) ----
        DBEventMember emProto = new DBEventMember();
        members = trans.fetchTable2(emProto,
                "where " + trans.markColumn(emProto.bp_idx) + " = " + event.bp_idx.toString()
                + " and " + trans.markColumn(emProto.event_idx) + " = " + event.idx.toString()
                + " order by " + trans.markColumn(emProto.name));

        feePerPerson = event.costs != null && event.costs.getValue() != null
                ? event.costs.getValue() : 0.0;

        plannedBudget = event.planned_costs != null && event.planned_costs.getValue() != null
                ? event.planned_costs.getValue() : 0.0;
        if (plannedBudget <= 0.0) {
            // fallback: sum the individual member fees (planned_costs is normally
            // maintained as exactly this sum by EventHelper)
            double sumCosts = 0.0;
            for (DBEventMember em : members) {
                if (em.costs != null && em.costs.getValue() != null) {
                    sumCosts += em.costs.getValue();
                }
            }
            plannedBudget = sumCosts;
        }

        // ---- booking lines linked to this event (via BOOKINGLINE2EVENTS) ----
        DBBookingLine2Events b2eProto = new DBBookingLine2Events();
        List<DBBookingLine2Events> links = trans.fetchTable2(b2eProto,
                "where " + trans.markColumn(b2eProto.bp_idx) + " = " + event.bp_idx.toString()
                + " and " + trans.markColumn(b2eProto.event_idx) + " = " + event.idx.toString());

        Set<Integer> blIds = new TreeSet<>();
        for (DBBookingLine2Events link : links) {
            if (link.bl_idx.getValue() != null && link.bl_idx.getValue() > 0) {
                blIds.add(link.bl_idx.getValue());
            }
        }

        bookingLines.clear();
        if (!blIds.isEmpty()) {
            StringBuilder ids = new StringBuilder();
            for (Integer id : blIds) {
                if (ids.length() > 0) {
                    ids.append(",");
                }
                ids.append(id);
            }
            DBBookingLine blProto = new DBBookingLine();
            bookingLines = trans.fetchTable2(blProto,
                    "where " + trans.markColumn(blProto.bp_idx) + " = " + event.bp_idx.toString()
                    + " and " + trans.markColumn(blProto.idx) + " in ( " + ids + " )"
                    + " order by " + trans.markColumn(blProto.date) + ", " + trans.markColumn(blProto.idx));
        }

        // ---- sums per account class (signed, like the cash flow report) ----
        bookingLinesTotal = 0.0;
        for (DBBookingLine bl : bookingLines) {
            double amount = bl.amount != null && bl.amount.getValue() != null
                    ? bl.amount.getValue() : 0.0;
            bookingLinesTotal += amount;
        }

        // ---- render HTML ----
        clear();
        html_start();
        html_setTitle("Event Settlement — " + event.name.toString()
                + (bp != null ? " (" + bp.title.toString() + ")" : ""));

        // Budget top (participants x fee = planned)
        text.append("<p><b>Budget</b><br/>")
            .append("Participants: ").append(members.size()).append("<br/>")
            .append("Fee per person: ").append(fmt(feePerPerson)).append(" €<br/>")
            .append("Budget (planned): ").append(fmt(plannedBudget)).append(" €</p>");

        html_newline();

        // Expense summary grouped by account class
        text.append("<h3>Expenses by account class</h3>");
        text.append("<table border='1' cellpadding='4' cellspacing='0' style='border-collapse:collapse;'>");
        text.append("<tr><th align='left'>Account Class</th><th align='right'>Sum (€)</th></tr>");

        Map<String, Double> sumByClass = getSumByClass();
        for (Map.Entry<String, Double> entry : sumByClass.entrySet()) {
            if (Math.abs(entry.getValue()) < 0.005) {
                continue; // skip empty classes for brevity
            }
            text.append("<tr><td>").append(escapeHtml(entry.getKey())).append("</td>")
                .append("<td align='right'>").append(fmt(entry.getValue())).append("</td></tr>");
        }

        text.append("<tr style='font-weight:bold'><td>Total from booking lines</td>")
            .append("<td align='right'>").append(fmt(bookingLinesTotal)).append("</td></tr>");

        double remaining = plannedBudget + bookingLinesTotal;
        text.append("<tr><td>Budget (planned)</td>")
            .append("<td align='right'>").append(fmt(plannedBudget)).append("</td></tr>");
        text.append("<tr style='font-weight:bold;background-color:#f0f0d0'><td>Remaining (Budget + Total)</td>")
            .append("<td align='right'>").append(fmt(remaining)).append("</td></tr>");
        text.append("</table>");

        html_newline();

        // Itemized booking lines
        text.append("<h3>Booking lines</h3>");
        text.append("<table border='1' cellpadding='4' cellspacing='0' style='border-collapse:collapse;'>");
        text.append("<tr><th align='left'>Date</th><th align='left'>Account Class</th>")
            .append("<th align='left'>Description</th><th align='right'>Amount (€)</th></tr>");

        for (DBBookingLine bl : bookingLines) {
            String dateStr = bl.date != null && bl.date.getValue() != null ? bl.date.getDateStr() : "";
            String cls = accountClassOf(bl);
            String desc = descriptionOf(bl);
            double amount = bl.amount != null && bl.amount.getValue() != null
                    ? bl.amount.getValue() : 0.0;
            text.append("<tr><td>").append(escapeHtml(dateStr)).append("</td>")
                .append("<td>").append(escapeHtml(cls)).append("</td>")
                .append("<td>").append(escapeHtml(desc)).append("</td>")
                .append("<td align='right'>").append(fmt(amount)).append("</td></tr>");
        }
        text.append("</table>");

        html_stop();
        return text.toString();
    }

    /** Account class name of a booking line, "(unassigned)" when empty. */
    private String accountClassOf(DBBookingLine bl) {
        if (bl.account_class != null && bl.account_class.getValue() != null
                && !bl.account_class.getValue().trim().isEmpty()) {
            return bl.account_class.getValue();
        }
        return UNASSIGNED;
    }

    /** Readable text of a booking line: comment when set, otherwise the booking text. */
    private String descriptionOf(DBBookingLine bl) {
        if (bl.comment != null && bl.comment.getValue() != null
                && !bl.comment.getValue().trim().isEmpty()) {
            return bl.comment.getValue();
        }
        if (bl.line != null && bl.line.getValue() != null
                && !bl.line.getValue().trim().isEmpty()) {
            return bl.line.getValue();
        }
        return bl.reference != null && bl.reference.getValue() != null
                ? bl.reference.getValue() : "";
    }

    private String fmt(double v) {
        return String.format("%.2f", v);
    }

    private static String escapeHtml(String s) {
        if (s == null) {
            return "";
        }
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    // ------------------------------------------------------------------
    // Getters for the ODS export (data is populated by render())
    // ------------------------------------------------------------------

    /** Signed sum of booking lines per account class name, sorted by name. */
    public Map<String, Double> getSumByClass() {
        // order classes alphabetically, "(unassigned)" last
        Comparator<String> cmp = (a, b) -> {
            boolean aU = a.equals(UNASSIGNED);
            boolean bU = b.equals(UNASSIGNED);
            if (aU != bU) {
                return aU ? 1 : -1;
            }
            return a.compareToIgnoreCase(b);
        };
        LinkedHashMap<String, Double> sorted = new LinkedHashMap<>();
        bookingLines.stream()
                .map(this::accountClassOf)
                .distinct()
                .sorted(cmp)
                .forEach(cls -> sorted.put(cls, sumOfClass(cls)));
        return sorted;
    }

    private double sumOfClass(String cls) {
        double s = 0.0;
        for (DBBookingLine bl : bookingLines) {
            if (accountClassOf(bl).equals(cls)) {
                s += bl.amount != null && bl.amount.getValue() != null ? bl.amount.getValue() : 0.0;
            }
        }
        return s;
    }

    public String getEventName() {
        return event.name.toString();
    }

    public DBBillingPeriod getBillingPeriod() {
        return bp;
    }

    public List<DBEventMember> getMembers() {
        return new ArrayList<>(members);
    }

    public int getParticipantCount() {
        return members.size();
    }

    public double getFeePerPerson() {
        return feePerPerson;
    }

    public double getPlannedBudget() {
        return plannedBudget;
    }

    public List<DBBookingLine> getBookingLines() {
        return new ArrayList<>(bookingLines);
    }

    public double getBookingLinesTotal() {
        return bookingLinesTotal;
    }

    public double getRemaining() {
        return plannedBudget + bookingLinesTotal;
    }
}
// AI-generated end
